import{_ as d,o as e,c as a,a6 as r}from"./chunks/framework.B_q3ZJNF.js";const s=JSON.parse('{"title":"简化清单：本课程与真实引擎的差距","description":"","frontmatter":{"title":"简化清单：本课程与真实引擎的差距"},"headers":[],"relativePath":"webgl-graphics-course/divergences.md","filePath":"webgl-graphics-course/docs/divergences.md"}'),h={name:"webgl-graphics-course/divergences.md"};function o(l,t,i,c,n,b){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="简化清单-本课程与真实引擎的差距" tabindex="-1">简化清单：本课程与真实引擎的差距 <a class="header-anchor" href="#简化清单-本课程与真实引擎的差距" aria-label="Permalink to &quot;简化清单：本课程与真实引擎的差距&quot;">​</a></h1><p>正文每处「本课程简化为……」「这笔账不展开」的集中登记。真实引擎/规范怎么做的写在右列——读得懂差距，才知道往哪走。</p><h2 id="实验场-companion-与规范的声明差异" tabindex="-1">实验场（companion）与规范的声明差异 <a class="header-anchor" href="#实验场-companion-与规范的声明差异" aria-label="Permalink to &quot;实验场（companion）与规范的声明差异&quot;">​</a></h2><table tabindex="0"><thead><tr><th>简化</th><th>真实行为</th><th>正文出处</th></tr></thead><tbody><tr><td><code>normalize([0,0,0])</code> 返回 <code>[0,0,0]</code>，不抛异常</td><td>GLSL 规范里结果未定义（除以零）</td><td><a href="./04-vectors.html">第 4 章</a>「一个边界约定」；测试锁住该差异</td></tr><tr><td><code>lookAt</code> 的 up 与视线平行时返回退化的约定值</td><td>规范未定义 gluLookAt 此情形；实现各异</td><td><a href="./07-camera-lookat.html">第 7 章</a>；测试锁住</td></tr><tr><td><code>orbitEye</code> 不收拢半径，调用方负责</td><td>真实相机库通常自带 min/max 距离约束</td><td><a href="./12-camera-controls.html">第 12 章</a>；bible API 契约声明</td></tr><tr><td><code>SceneNode.world</code> 是结算快照，不是活引用</td><td>真实引擎有脏标记增量更新，避免全树重算</td><td><a href="./11-scene-graph.html">第 11 章</a></td></tr><tr><td>实验场零 GL 调用——GL 接线由正文内嵌演示承担</td><td>真实渲染库封装 GL 上下文</td><td>第 1 章开篇约定</td></tr></tbody></table><h2 id="教学叙事的简化" tabindex="-1">教学叙事的简化 <a class="header-anchor" href="#教学叙事的简化" aria-label="Permalink to &quot;教学叙事的简化&quot;">​</a></h2><table tabindex="0"><thead><tr><th>简化</th><th>真实行为</th><th>正文出处</th></tr></thead><tbody><tr><td>第 2 章把「裁剪坐标系」与 NDC 混着叫（w=1 特例下两者重合）</td><td>裁剪坐标是未除 w 的半成品，NDC 是除 w 之后——第 6 章正式分家</td><td><a href="./02-first-triangle.html">第 2 章</a> NDC 首现；<a href="./06-projection.html">第 6 章</a></td></tr><tr><td>UV 演算选整刻度点手算，纹素中心对齐（半纹素偏移）不展开</td><td>真实 NEAREST 按纹素中心判定，恰落边界时四纹素平手</td><td><a href="./09-textures.html">第 9 章</a> 演算括注</td></tr><tr><td>LINEAR 过滤只演 u 一根轴的两纹素混合</td><td>2D 纹理是 2×2 四纹素加权平均（双线性）</td><td><a href="./09-textures.html">第 9 章</a> 过滤演算括注</td></tr><tr><td>mipmap（多级渐远纹理）不展开，MIN/MAG 设同档绕开</td><td>真实管线用 mipmap 做缩小抗噪；MIN 默认值就要求它</td><td><a href="./09-textures.html">第 9 章</a>「默认值的坑」</td></tr><tr><td>深度缓冲精度只记账（24 bit、非线性分布）不展开</td><td>真实引擎要处理 z-fighting、对数深度等精度病</td><td><a href="./08-depth-and-cube.html">第 8 章</a>「z 是怎么变成远近的」</td></tr><tr><td>漫游相机是 fly 风格（严格沿基向量，抬头按 W 离地）</td><td>贴地行走要把 forward 压平再归一化（向量投影的活）</td><td><a href="./12-camera-controls.html">第 12 章</a> 边界说明；练习路线留作习题</td></tr><tr><td>Phong 是经验光照模型</td><td>真实渲染走物理模型（BRDF/PBR），能量守恒</td><td><a href="./10-lighting.html">第 10 章</a>；<a href="./14-beyond-webgl.html">第 14 章</a> 库增值清单</td></tr><tr><td>课程停在 WebGL 1（教学最小内核）</td><td>WebGL 2 几乎严格超集、WebGPU 是下一代——概念不作废</td><td><a href="./14-beyond-webgl.html">第 14 章</a></td></tr></tbody></table><h2 id="演示组件与实验场的声明偏差" tabindex="-1">演示组件与实验场的声明偏差 <a class="header-anchor" href="#演示组件与实验场的声明偏差" aria-label="Permalink to &quot;演示组件与实验场的声明偏差&quot;">​</a></h2><table tabindex="0"><thead><tr><th>偏差</th><th>原因</th><th>出处</th></tr></thead><tbody><tr><td>DemoTextureCube 的纹理数据按图片行序生成（顶行在前）、左下格染红、深浅灰两档</td><td>让 UNPACK_FLIP_Y 开关有戏可唱、方向可读；实验场 checkerboard 是底边行序、纯黑白</td><td><a href="./09-textures.html">第 9 章</a>；组件注释与 bible 声明</td></tr><tr><td>DemoSolarSystem 的法线直接用模型矩阵变换</td><td>受光球体全是均匀缩放，两种算法此情形等价（第 10 章的账）</td><td>组件注释声明</td></tr><tr><td>DemoWorld 片元着色器给自发光免雾（factor 乘 (1−emissive)）</td><td>太阳距入口约 30 格 &gt; 雾 far=28，不免雾会被雾完全吃掉</td><td><a href="./13-build-3d-world.html">第 13 章</a> 雾节声明</td></tr><tr><td>DemoWorld 不建场景树、清单生成时直接收行</td><td>该世界全树深度 1，collectRenderList 的遍历退化为顺序枚举</td><td><a href="./13-build-3d-world.html">第 13 章</a> 演示节声明</td></tr><tr><td>DemoWorld 滚轮调移动速度而非缩放</td><td>漫游相机上调速比缩放更贴身；缩放在第 12 章轨道侧兑现</td><td><a href="./13-build-3d-world.html">第 13 章</a> 演示节声明</td></tr></tbody></table><h2 id="终点世界的教学简化" tabindex="-1">终点世界的教学简化 <a class="header-anchor" href="#终点世界的教学简化" aria-label="Permalink to &quot;终点世界的教学简化&quot;">​</a></h2><table tabindex="0"><thead><tr><th>简化</th><th>真实行为</th><th>正文出处</th></tr></thead><tbody><tr><td>世界不查碰撞（柱廊与房子可能重叠）</td><td>真实引擎上碰撞检测与空间划分</td><td><a href="./13-build-3d-world.html">第 13 章</a>「一处诚实声明」</td></tr><tr><td>雾参数固定（near 8 / far 28），不随种子</td><td>雾是气氛不是布局</td><td>同上；JSDoc 与 bible 声明</td></tr><tr><td>每个物体一个 draw call（17 行清单）</td><td>真实引擎合批、实例化、剔除（第 14 章讲了去向）</td><td><a href="./14-beyond-webgl.html">第 14 章</a></td></tr></tbody></table>',10)])])}const f=d(h,[["render",o]]);export{s as __pageData,f as default};
